const d = $json;
const lines = [
  `# Daily Eval Report — ${new Date().toISOString().slice(0,10)}`,
  '',
  `- **Branch**: ${d.branch_id || 'n/a'}`,
  `- **Chapter count**: ${d.chapter_count ?? 'n/a'}`,
  `- **Total facts**: ${d.total_facts ?? 'n/a'}`,
  `- **Avg confidence**: ${(d.avg_confidence ?? 0).toFixed(3)}`,
  `- **Low-confidence facts**: ${d.low_confidence_count ?? 'n/a'}`,
  `- **Open foreshadowing threads**: ${(d.open_threads || []).length}`,
  '',
  '_generated by n8n daily-eval-report_'
];
const markdown = lines.join('\n');
console.log(markdown);
return [{ json: { markdown, branch_id: d.branch_id } }];
